def F(key,label,kind='text',default='',options=None,path=None,**kw):
    d=dict(key=key,label=label,type=kind,default=default,**kw)
    if options is not None: d['options']=options
    if path: d['path']=path
    return d
def choice(k,l,opts,default=None,**kw): return F(k,l,'choice',default or opts[0],opts,**kw)
def num(k,l,default=0,path=None,**kw): return F(k,l,'number',default,path=path,**kw)
