def G(path,value,label,op='eq'): return dict(path=path,value=value,label=label,op=op)
def M(title,category,server,topic,description,symptoms,patch,goals,solution,hints,explanation,difficulty='Pokročilý',priority='Vysoká'):
    id=len(missions)+1
    goals=goals+[G('diagnostic.viewed',True,'Provedena diagnostika')]
    missions.append(dict(id=id,title=title,category=category,server=server,topic=topic,difficulty=difficulty,priority=priority,description=description,symptoms=symptoms,initial_state=patch,available_actions=list(dict.fromkeys(x[0] for x in solution))+['inspect','verify'],objectives=goals,failure_conditions=['Neověřená změna','Rizikový zásah do původních dat'],hints=hints,explanations=explanation,rewards={'xp':300}))
    solutions.append([['inspect',{'scope': 'Storage' if category=='Storage' else 'Events'}]]+solution+[['verify',{}]])
